// usage: node scripts/release-metadata.mjs [--version <x.y.z>]
// Fills the release folder's text parts (release/v<version>/, default version: tauri.conf.json's):
//   metadata/  RELEASE-NOTES.md (docs/release-notes-<version>.md), PRIVACY-POLICY.md, TERMS-OF-USE.md, EULA.md,
//              LICENSE.txt, THIRD-PARTY-LICENSES.txt (from licenses/, generated by pnpm build)
//   launchers/ windows/Start OpenMind Studio.bat, linux/openmind-studio.sh, macos/Start OpenMind Studio.command
// latest.json and SHA256SUMS.txt are written by release.mjs / release-checksums.mjs; nothing here touches artifacts.
import { copyFileSync, existsSync, mkdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { METADATA_DIR, releaseDir } from "./releaseTools.mjs";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const args = process.argv.slice(2);
const at = args.indexOf("--version");
const version =
  at >= 0
    ? args[at + 1]
    : JSON.parse(readFileSync(join(root, "src-tauri", "tauri.conf.json"), "utf8")).version;
const out = releaseDir(root, version);

const copies = [
  [join("docs", `release-notes-${version}.md`), join(METADATA_DIR, "RELEASE-NOTES.md")],
  [join("licenses", "legal", "PRIVACY-POLICY.md"), join(METADATA_DIR, "PRIVACY-POLICY.md")],
  [join("licenses", "legal", "TERMS-OF-USE.md"), join(METADATA_DIR, "TERMS-OF-USE.md")],
  [join("licenses", "legal", "EULA.md"), join(METADATA_DIR, "EULA.md")],
  ["LICENSE", join(METADATA_DIR, "LICENSE.txt")],
  [join("licenses", "THIRD-PARTY-LICENSES.txt"), join(METADATA_DIR, "THIRD-PARTY-LICENSES.txt")],
  [
    join("scripts", "launchers", "windows", "Start OpenMind Studio.bat"),
    join("launchers", "windows", "Start OpenMind Studio.bat"),
  ],
  [
    join("scripts", "launchers", "linux", "openmind-studio.sh"),
    join("launchers", "linux", "openmind-studio.sh"),
  ],
  [
    join("scripts", "launchers", "macos", "Start OpenMind Studio.command"),
    join("launchers", "macos", "Start OpenMind Studio.command"),
  ],
];
const missing = copies.filter(([from]) => !existsSync(join(root, from))).map(([from]) => from);
if (missing.length > 0) {
  console.error(`Missing (run pnpm build for licenses/):\n- ${missing.join("\n- ")}`);
  process.exit(1);
}
for (const [from, to] of copies) {
  mkdirSync(dirname(join(out, to)), { recursive: true });
  copyFileSync(join(root, from), join(out, to));
}
console.log(`Wrote ${copies.length} files into ${out} (metadata/, launchers/).`);
